53	 * Set the user's location from Settings.
54	 *
55	 * WHY THIS EXISTS SEPARATELY FROM `saveLocation`: that one runs inside the
56	 * Stylist's `applyResult`, where the timezone is already in hand from the
57	 * generate that just happened. Settings has no generate — and location cannot be
58	 * written without a timezone, because `localDateFor` and `predictDefaultOccasion`
59	 * read `location_timezone` and a null falls back to UTC, which is exactly the
60	 * failure Decision 5 exists to prevent (a UTC key rolls the daily drop over
61	 * mid-evening). So this resolves one first. That is one Open-Meteo call, no API
62	 * key, no AI, and `fetchForecast` already caches it 30 minutes per rounded
63	 * coordinate.
64	 *
65	 * A picked city is always `source: "city"` — `resolveLocation` surfaces that as
66	 * the origin, and it is what suppresses the Stylist's silent GPS refresh so a
67	 * deliberate choice is not overwritten on the next load.
68	 */
69	export async function setLocation(input: unknown): Promise<void> {
70	  const picked = PickedCitySchema.parse(input);
71	
72	  const supabase = await createClient();
73	  const {
74	    data: { user },
75	  } = await supabase.auth.getUser();
76	  if (!user) throw new Error("Not signed in");
77	
78	  const { data: profile } = await supabase
79	    .from("profiles")
80	    .select("location_lat, location_lon, location_timezone")
81	    .eq("id", user.id)
82	    .single();
83	
84	  // Resolve the timezone BEFORE writing anything. If this throws, the old
85	  // location survives — better than storing one with a null timezone.
86	  const forecast = await fetchForecast(picked.lat, picked.lon);
87	
88	  const moved = locationChanged(picked, profile);
89	
90	  const { error } = await supabase
91	    .from("profiles")
92	    .update(
93	      locationColumns(
94	        { ...picked, source: "city", timezone: forecast.timezone },
95	        new Date().toISOString(),
96	      ),
97	    )
98	    .eq("id", user.id);
99	  if (error) throw new Error(error.message);
100	
101	  if (moved) await clearTodaysDrop(supabase, user.id, forecast.timezone);
102	
103	  revalidatePath("/settings");
104	  revalidatePath("/generate");
105	}
