42	export async function generate(input: {
43	  occasion: UiOccasion;
44	  formality: number | null;
45	  /** Refine "Lean into" colour families (`COLOR_FAMILIES` keys). A preference, not a filter. */
46	  lean: string[];
47	  /** Explicit user action only — the one way to spend an AI call on a day already answered. */
48	  regenerate?: boolean;
49	  city?: { lat: number; lon: number; label: string; source: LocationSource };
50	}): Promise<GenerateResult> {
51	  try {
52	    const supabase = await createClient();
53	    const {
54	      data: { user },
55	    } = await supabase.auth.getUser();
56	    if (!user) return { status: "error", message: "Not signed in" };
57	
58	    const { data: profile } = await supabase
59	      .from("profiles")
60	      .select(
61	        "archetype, formality_min, formality_max, location_lat, location_lon, location_label, location_source, preferences",
62	      )
63	      .eq("id", user.id)
64	      .single();
65	    const { data: itemsRaw } = await supabase
66	      .from("items")
67	      .select("*")
68	      .eq("user_id", user.id)
69	      .eq("archived", false);
70	    const items = itemsRaw ?? [];
71	    const byId = new Map(items.map((i) => [i.id, i]));
72	    const pathFor = (id: string) => {
73	      const it = byId.get(id);
74	      return it ? displayPath(it) : undefined;
75	    };
76	
77	    const loc = resolveLocation({ input: input.city, profile });
78	
79	    const now = new Date();
80	    const f = await fetchForecast(loc.lat, loc.lon);
81	    const prefs = readPreferences(profile?.preferences);
82	    const advice = laterAdvice(f.hourly, prefs.tempUnit);
83	    const weather: WeatherPayload = {
84	      tempC: f.tempC,
85	      feelsLikeC: f.feelsLikeC,
86	      condition: f.condition,
87	      cityLabel: loc.label,
88	      timezone: f.timezone,
89	      locationOrigin: loc.origin,
90	      laterSentence: advice.sentence,
91	      adviceClause: advice.adviceClause,
92	      laterLabel: "Later",
93	      hourly: f.hourly,
94	      tempUnit: prefs.tempUnit,
95	    };
96	
97	    const today = localDateFor(now, f.timezone);
98	
99	    // The daily drop (Decision 5): today's looks are generated once and then
100	    // read back. Only an explicit regenerate spends an AI call on a day the
101	    // stylist has already answered.
102	    //
103	    // The stored set is read on BOTH paths. On a normal load it IS the answer;
104	    // on a regenerate it is the recency signal — the pieces the user just
105	    // rejected, which ranking will sink without ever filtering them out.
106	    const stored = await loadDailyLooks(user.id, input.occasion, today);
107	
108	    if (!input.regenerate && stored?.length) {
109	      const paths = Array.from(
110	        new Set(
111	          stored
112	            .flatMap((s) => s.pieces.map((p) => byId.get(p.itemId)))
113	            .filter((it): it is NonNullable<typeof it> => Boolean(it))
114	            .map((it) => displayPath(it)),
115	        ),
116	      );
117	      const signed = await signItemImages(paths);
118	      const looks = reassembleLooks(stored, byId, signed, pathFor);
119	      // null = the closet changed under the stored set; fall through and
120	      // regenerate rather than showing an outfit with a hole in it.
121	      if (looks) return { status: "ok", weather, looks };
122	    }
123	
124	    // Only a deliberate regenerate carries the signal. A fall-through from a
125	    // stale stored set is the app fixing itself, not the user asking for
126	    // something else — penalising those pieces would be arbitrary.
127	    const recentlyShown = input.regenerate
128	      ? Array.from(new Set(stored?.flatMap((s) => s.pieces.map((p) => p.itemId)) ?? []))
129	      : [];
130	
131	    /**
132	     * A fall-through is a DROP, not a regenerate.
133	     *
134	     * Reaching here without `input.regenerate` means either the occasion has no
135	     * looks today, or the stored set no longer reassembles because the closet
136	     * changed under it. Both are the app answering for the first time or
137	     * repairing its own bookkeeping — not the user asking again — and neither
138	     * should be charged. Drops are free on every tier regardless, so the
139	     * distinction only matters for what the ledger records.
140	     */
141	    const gen: GenerationRequest = {
142	      kind: input.regenerate ? "regenerate" : "drop",
143	      occasion: input.occasion,
144	      today,
145	    };
146	    // Caught HERE rather than in the outer catch, for two reasons: `weather` is
147	    // in scope so the screen keeps its strip instead of collapsing, and being
148	    // limited is a STATE, not a failure — routing it through the error path
149	    // would render "Couldn't reach the stylist" for a working app.
150	    try {
151	      await assertCanGenerate(user.id, gen);
152	    } catch (e) {
153	      if (e instanceof QuotaExceededError) {
154	        return { status: "limited", weather, message: e.message };
155	      }
156	      throw e;
157	    }
158	
159	    const candItems: CandidateItem[] = items.map((i) => ({
160	      id: i.id,
161	      category: i.category,
162	      colors: i.colors ?? [],
163	      formality: i.formality,
164	      seasons: i.seasons ?? [],
165	      material: i.material,
166	    }));
167	    // Occasion gives the context; the user's onboarding dress codes narrow it;
168	    // an explicit Refine formality overrides both.
169	    const band = applyFormalityOverride(
170	      personalBand(input.occasion, profile),
171	      input.formality,
172	    );
173	    const candidateArgs = {
174	      band,
175	      weather: { tempC: f.tempC, rain: f.hourly.some((h) => h.isNow && h.rain) },
176	      season: currentSeason(now),
177	      excludeItemIds: [],
178	      maxAccessories: 1,
179	      rainGuard: prefs.rainGuard,
180	    };
181	    const combos = buildCandidates(candItems, candidateArgs);
182	    if (combos.length === 0) {
183	      return { status: "empty", weather, missing: missingCategory(candItems, candidateArgs) };
184	    }
185	
186	    const aesthetic = profile?.archetype ? [profile.archetype] : [];
187	    // The Refine colour pick lands here, in ranking — not in candidate building.
188	    // It reorders the shortlist toward the requested families and is dropped
189	    // silently when the closet cannot honour it.
190	    //
191	    // Rank everything, then spread the shortlist across the wardrobe before the
192	    // re-ranker sees it. Taking the top 20 by score alone clusters — a neutral
193	    // top harmonises with everything, so it occupies most of the list, and "the
194	    // best 3" of a clustered list is three versions of one outfit. Diversifying
195	    // the INPUT makes the model's three distinct by construction.
196	    // Season rides along as a ranking preference — in-season combos float to the
197	    // top of the shortlist the re-ranker sees, but an off-season one is still
198	    // offered rather than the screen going empty.
199	    const ranked = rankTopN(
200	      combos,
201	      { aesthetic, band, lean: input.lean, recentlyShown, season: candidateArgs.season },
202	      combos.length,
203	    );
204	    const top = diversify(ranked, 20);
205	
206	    // A look the user has already worn today is PINNED: saveDailyLooks leaves it
207	    // in place, so it has to survive in what we hand back to the screen too —
208	    // otherwise the day's set silently loses it until the next page load. It
209	    // also still COUNTS toward the day's three, so the stylist is asked for
210	    // fewer fresh looks rather than the set growing a fourth tab.
211	    const pinnedStored = (stored ?? []).filter((s) => s.worn);
212	
213	    const { picks } = await rerank({
214	      want: MAX_PICKS - pinnedStored.length,
215	      combos: top.map((t) =>
216	        t.items.map((ci) => {
217	          const it = byId.get(ci.id)!;
218	          return { category: it.category, subcategory: it.subcategory, colors: it.colors ?? [] };
219	        }),
220	      ),
221	      aesthetic,
222	      occasion: input.occasion,
223	      weatherLabel: f.condition,
224	      tempC: f.tempC,
225	    });
226	
227	    const paths = Array.from(
228	      new Set([
229	        ...top.flatMap((t) => t.items.map((ci) => displayPath(byId.get(ci.id)!))),
230	        ...pinnedStored.flatMap((s) =>
231	          s.pieces.map((p) => pathFor(p.itemId)).filter((p): p is string => Boolean(p)),
232	        ),
233	      ]),
234	    );
235	    const signed = await signItemImages(paths);
236	
237	    // `rerank` already dropped picks that repeat a combo or point outside the
238	    // shortlist, so every index here resolves. It previously fell back to
239	    // `top[0]` for an unknown index, which turned a bad index into a duplicate
240	    // of the first look rather than into one fewer look.
241	    const drafts: LookDraft[] = picks.map((p) => {
242	      const combo = top[p.combo_index].items;
243	      const dbItems = combo.map((ci) => byId.get(ci.id)!);
244	      const slots = layoutForLook(dbItems.map((d) => ({ category: d.category })));
245	      const pieces: LookPiece[] = dbItems.map((d, idx) => ({
246	        itemId: d.id,
247	        category: d.category,
248	        subcategory: d.subcategory ?? null,
249	        brand: d.brand ?? null,
250	        name: d.name ?? null,
251	        colors: d.colors ?? [],
252	        cutoutUrl: signed.get(displayPath(d)) ?? "",
253	        slot: slots[idx],
254	      }));
255	      return { name: p.name, why: p.why, pieces, anchorIndex: staggerOrder(slots)[0] };
256	    });
257	
258	    // Fire-and-forget would be simpler, but a failed write means the user pays
259	    // for another AI call on their next tap — worth awaiting. The insert also
260	    // hands back the row ids, which are the detail screen's address.
261	    const ids = await saveDailyLooks(user.id, input.occasion, today, weather, drafts);
262	    const fresh: Look[] = drafts.map((d, i) => ({ ...d, id: ids[i] ?? "", worn: false }));
263	
264	    // Recorded only now — after the model answered and the write succeeded. A
265	    // generation that failed cost the user nothing, so metering it would be
266	    // charging them for our error.
267	    await noteGeneration(user.id, gen);
268	
269	    // Pinned looks keep their place at the front — they hold the lower
270	    // look_index values, which is the order the next load will read them back in.
271	    const pinned = reassembleLooks(pinnedStored, byId, signed, pathFor) ?? [];
272	
273	    return { status: "ok", weather, looks: [...pinned, ...fresh] };
274	  } catch (e) {
275	    console.error("[generate] failed:", e);
276	    return { status: "error", message: e instanceof Error ? e.message : "Generation failed" };
277	  }
278	}
