2	import { roundCoord } from "@/lib/weather/location";
3	
4	export const RAIN_CODES = new Set([51, 53, 55, 61, 63, 65, 80, 81, 82, 95, 96, 99]);
5	
6	type Raw = {
7	  timezone: string;
8	  current: {
9	    time: string;
10	    temperature_2m: number;
11	    apparent_temperature: number;
12	    weather_code: number;
13	  };
14	  hourly: {
15	    time: string[];
16	    temperature_2m: number[];
17	    weather_code: number[];
18	    precipitation_probability: number[];
19	  };
20	};
21	
22	function conditionFor(code: number): string {
23	  if (RAIN_CODES.has(code)) return "Rain";
24	  if (code === 0) return "Clear";
25	  if (code <= 2) return "Partly cloudy";
26	  return "Overcast";
27	}
28	
29	/** "2026-01-14T18:00" → "18:00" */
30	function hhmm(iso: string): string {
31	  return (iso.split("T")[1] ?? "").slice(0, 5);
32	}
33	
34	/**
35	 * Pure — never calls the clock. `nowIso` defaults to `raw.current.time`, which is
36	 * local time AT THE LOCATION (because we send timezone=auto) and therefore on the
37	 * same clock as `raw.hourly.time`. Callers may still inject a now for tests.
38	 */
39	export function mapForecast(
40	  raw: Raw,
41	  nowIso: string = raw.current.time,
42	): { tempC: number; feelsLikeC: number; condition: string; timezone: string; hourly: HourCell[] } {
43	  const times = raw.hourly.time;
44	  let nowIdx = times.findIndex((t) => t >= nowIso); // first hour at/after now
45	  if (nowIdx < 0) nowIdx = 0;
46	
47	  const hourly: HourCell[] = [];
48	  for (let k = 0; k < 4 && nowIdx + k < times.length; k++) {
49	    const i = nowIdx + k;
50	    hourly.push({
51	      hh: hhmm(times[i]),
52	      tempC: Math.round(raw.hourly.temperature_2m[i]),
53	      rain: RAIN_CODES.has(raw.hourly.weather_code[i]),
54	      isNow: k === 0,
55	    });
56	  }
57	
58	  return {
59	    tempC: Math.round(raw.current.temperature_2m),
60	    feelsLikeC: Math.round(raw.current.apparent_temperature),
61	    condition: conditionFor(raw.current.weather_code),
62	    timezone: raw.timezone,
63	    hourly,
64	  };
65	}
