67	export async function fetchForecast(lat: number, lon: number, nowIso?: string) {
68	  // Round at the boundary: every caller gets a cache-friendly URL, and raw GPS
69	  // precision never reaches Open-Meteo. timezone=auto makes both `current.time`
70	  // and `hourly.time` local to the coords (otherwise they come back as GMT).
71	  const la = roundCoord(lat);
72	  const lo = roundCoord(lon);
73	  const url =
74	    `https://api.open-meteo.com/v1/forecast?latitude=${la}&longitude=${lo}` +
75	    `&current=temperature_2m,apparent_temperature,weather_code` +
76	    `&hourly=temperature_2m,weather_code,precipitation_probability` +
77	    `&forecast_hours=24&timezone=auto`;
78	  const res = await fetch(url, { next: { revalidate: 1800 } });
79	  return mapForecast(await res.json(), nowIso);
80	}
